"""Write tiny, synthetic release-gate media. Contains no user data."""

from __future__ import annotations

import base64
from pathlib import Path
import sys


FIXTURES = {
    "portrait.mp4": "",
    "synthetic.mp4": "",
    "synthetic.gif": "",
    "synthetic.webp": "UklGRi4AAABXRUJQVlA4ICIAAAAwAQCdASoCAAIAAgA0JaAAA3AA/u69R//8wT/0k/43dcgA",
}


def main() -> int:
    if len(sys.argv) != 2:
        raise SystemExit("usage: write_media_fixtures.py DIRECTORY")
    destination = Path(sys.argv[1])
    destination.mkdir(parents=True, exist_ok=True)
    for name, encoded in FIXTURES.items():
        (destination / name).write_bytes(base64.b64decode(encoded, validate=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
